"use client";

import { useState, useMemo } from "react";
import { ChevronLeft, ChevronRight, Plus, X } from "lucide-react";
import { format, addMonths, subMonths, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameMonth, isSameDay, addDays } from "date-fns";
import { nl } from "date-fns/locale"; 
import { createCalendarItem } from "@/app/actions/task-actions";
import { useRouter } from "next/navigation";

export default function CalendarClient({ initialTasks = [] }: { initialTasks: any[] }) {
  const router = useRouter();
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [loading, setLoading] = useState(false);
  const [title, setTitle] = useState("");
  const [type, setType] = useState("agenda");

  // VERİLERİ GÜNLERE EŞLEŞTİRME (EN SAĞLAM HALİ)
  const taskMap = useMemo(() => {
    const map: any = {};
    initialTasks.forEach((item) => {
      if (item.startDatetime) {
        // DB'den gelen karmaşık tarihi temiz bir "2024-05-20" formatına çeviriyoruz
        const d = new Date(item.startDatetime);
        const dateKey = format(d, "yyyy-MM-dd");
        if (!map[dateKey]) map[dateKey] = [];
        map[dateKey].push(item);
      }
    });
    return map;
  }, [initialTasks]);

  const handleSave = async () => {
    if (!title || !selectedDate) return;
    setLoading(true);

    const payload = {
      titel: title,
      documentType: type,
      datum: format(selectedDate, "yyyy-MM-dd"), // "2024-10-25" gibi temiz veri
    };

    try {
      const res = await createCalendarItem(payload);
      if (res.success) {
        setTitle("");
        setSelectedDate(null);
        // Veriyi çekmek için Next.js'i zorla tazeliyoruz
        router.refresh();
        setTimeout(() => window.location.reload(), 500);
      } else {
        alert("Opslaan mislukt: " + res.error);
      }
    } catch (err) {
      console.error("Fout:", err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-[1600px] mx-auto px-4 py-8">
      {/* HEADER */}
      <div className="flex justify-between items-center mb-8 border-b border-white/5 pb-6">
        <h1 className="text-4xl font-black text-white italic uppercase tracking-tighter">Temporal Grid</h1>
        <div className="flex items-center gap-4 bg-[#0a0e17] border border-white/10 p-2 rounded-xl text-white">
          <button onClick={() => setCurrentMonth(subMonths(currentMonth, 1))} className="p-2 text-teal-500 cursor-pointer"><ChevronLeft /></button>
          <span className="text-lg font-bold w-44 text-center">{format(currentMonth, "MMMM yyyy", { locale: nl })}</span>
          <button onClick={() => setCurrentMonth(addMonths(currentMonth, 1))} className="p-2 text-teal-500 cursor-pointer"><ChevronRight /></button>
        </div>
      </div>

      {/* TAKVİM */}
      <div className="bg-[#0a0e17]/80 border border-white/10 rounded-3xl overflow-hidden shadow-2xl">
        <div className="grid grid-cols-7 bg-white/5 py-4 border-b border-white/10 text-center text-[10px] font-black text-teal-500/40 uppercase tracking-widest">
          {["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"].map(d => <span key={d}>{d}</span>)}
        </div>
        <div className="grid grid-cols-7">
          {(() => {
            const days = [];
            let day = startOfWeek(startOfMonth(currentMonth), { weekStartsOn: 1 });
            const endDate = endOfWeek(endOfMonth(currentMonth), { weekStartsOn: 1 });

            while (day <= endDate) {
              const dateKey = format(day, "yyyy-MM-dd");
              const dayTasks = taskMap[dateKey] || [];
              const isCurrentMonth = isSameMonth(day, currentMonth);
              const currentDay = day;

              days.push(
                <div 
                  key={day.toString()} 
                  onClick={() => setSelectedDate(currentDay)}
                  className={`min-h-[150px] border border-white/5 p-4 hover:bg-fuchsia-500/5 cursor-pointer relative ${!isCurrentMonth ? "opacity-10 pointer-events-none" : "opacity-100"}`}
                >
                  <span className="text-xs text-teal-500/30 mb-2 block">{format(day, "d")}</span>
                  <div className="space-y-1">
                    {dayTasks.map((t: any) => (
                      <div key={t.id} className={`text-[9px] px-2 py-1 truncate rounded border font-bold uppercase ${
                        t.description === 'agenda' || t.description === 'assignment' 
                        ? 'bg-blue-600/10 border-blue-500/30 text-blue-400' 
                        : 'bg-fuchsia-600/10 border-fuchsia-500/30 text-fuchsia-400'
                      }`}>
                        {t.title}
                      </div>
                    ))}
                  </div>
                </div>
              );
              day = addDays(day, 1);
            }
            return days;
          })()}
        </div>
      </div>

      {/* MODAL / FORM */}
      {selectedDate && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-sm p-4">
          <div className="bg-[#0E153A] border border-fuchsia-500/40 p-8 rounded-[32px] w-full max-w-md relative">
            <button onClick={() => setSelectedDate(null)} className="absolute top-6 right-6 text-white/30 hover:text-white cursor-pointer"><X /></button>
            <h3 className="text-fuchsia-500 font-black text-[10px] tracking-widest uppercase mb-2">Toevoegen</h3>
            <p className="text-2xl font-bold text-white mb-6 uppercase italic">{format(selectedDate, "dd MMMM yyyy", { locale: nl })}</p>
            
            <div className="space-y-6">
              <input 
                autoFocus 
                value={title} onChange={(e) => setTitle(e.target.value)} 
                className="w-full bg-[#070B24] border border-white/10 p-4 text-white font-bold rounded-xl outline-none focus:border-fuchsia-500" 
                placeholder="Wat gaan we doen?" 
              />
              <div className="grid grid-cols-2 gap-3">
                {['agenda', 'assignment', 'meeting', 'daily'].map(cat => (
                  <button key={cat} onClick={() => setType(cat)} className={`py-3 text-[10px] font-black uppercase border rounded-lg transition-all ${type === cat ? 'bg-fuchsia-600 border-fuchsia-600 text-white' : 'bg-[#070B24] border-white/5 text-white/40'}`}>{cat}</button>
                ))}
              </div>
              <button 
                onClick={handleSave} 
                disabled={loading || !title} 
                className="w-full bg-white text-[#0E153A] font-black py-4 mt-2 hover:bg-fuchsia-500 hover:text-white transition-all uppercase text-xs rounded-xl disabled:opacity-20"
              >
                {loading ? "Opslaan..." : "Bevestigen"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}